// CSD_RATIONALE_BEGIN
// GSM-symbolic strategy. Tracked state: `generated` (full visible answer text
// including "<<"/">>" delimiters), `insideConstrainedOut` (whether a symbolic
// expression span is currently open), `currentConstrainedOut` (only the
// contents of the open span), plus a local `steps` counter that is exactly the
// token budget consumed, and a `spanCount` counter of how many expression spans
// have been closed so far.
//
// Observations used to choose the next action:
//   * Outside a span, the strategy decodes freely so the model can write its
//     "Let's think step by step" reasoning prose; it watches for the model's own
//     "<<" token and then switches to constrained mode with
//     EnterObservedConstrainedSpan-style bookkeeping (here inline: set inside
//     and reset current), spending no extra delimiter token.
//   * Inside a span, it first tries CloseSpanIfComplete: as soon as the partial
//     expression is a complete parse the span is closed with ">>" and free
//     reasoning resumes. Otherwise it takes one hard parser-controlled step.
//     Early in a span (few tokens so far) it prefers group-boosted decoding so
//     caller-supplied vocabulary (variable names, digits, the allowed operators
//     + - / // % ( ) int) is favored; later in the span it switches to an
//     adaptive step with a penalty on tokens that would restart a nested span
//     or emit disallowed operators, which keeps expressions single-line and in
//     the permitted operator set.
//   * A repetition-penalized step is used when the current span has already
//     grown long, discouraging the degenerate loops that make symbolic answers
//     unparseable.
// This state supports valid generation because every visible expression byte is
// emitted under parser control, spans are only closed at complete parses, and
// the final answer span is therefore always a well-formed symbolic expression.
// AppendTaskGuidance carries the meaning the grammar cannot: which quantities
// are whole counts, how "per"/"percent"/"each" distribute, and that variable
// names from the question must be preserved symbolically.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   * Unconstrained branch: if the sampled token is not "<<", insideConstrainedOut
//     stays false and currentConstrainedOut stays [], so the implication is
//     vacuous. If it is "<<", we set currentConstrainedOut := [], and
//     parser.IsValidPrefix([]) holds by the method precondition.
//   * Close branch (CloseSpanIfComplete returns closed): the helper sets
//     insideOut := false and currentOut := [], so the implication is vacuous and
//     the !inside ==> current == [] invariant holds too.
//   * Constrained-step branches (GroupBoostedConstrainedStep,
//     SafeRepetitionPenaltyStep, AdaptiveConstrainedStepWithPenalties): each
//     returns either eosToken (we break, state unchanged and still valid) or a
//     parser-valid next token; AppendConstrainedToken's postcondition then gives
//     parser.IsValidPrefix(currentConstrainedOut + [next]) and keeps
//     |currentConstrainedOut| <= |generated|.
// progress (|generated| <= |generatedPrefix| + steps):
//   * Unconstrained branch consumes 1 token-step (steps + 1) and appends at most
//     one visible token (zero on EOS), so growth <= budget consumed.
//   * Close branch consumes 1 token-step and appends at most one visible ">>"
//     token (zero when the grammar already emitted it), so growth <= 1 = the
//     increment of steps.
//   * Constrained-step branches consume exactly 1 token-step each, including
//     when the token is EOS (which is counted but not appended), and append at
//     most one visible token via AppendConstrainedToken, so growth <= 1.
//   Hence at loop exit |generated| <= |generatedPrefix| + steps <= |generatedPrefix| + maxSteps
//   and cost = steps <= maxSteps. If maxSteps > 0 the loop body executes at least
//   once and every branch increments steps, so cost > 0 whenever maxSteps > 0.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string :=
  "Interpret the word problem symbolically: every named quantity given in the question keeps its variable name in the arithmetic rather than being replaced by an invented number, and only quantities actually stated in the question (or derived from them) may appear. 'each'/'per' means the stated rate multiplies the number of items it distributes over; 'p percent of q' means q*p/100; 'twice/half as many' scales the referenced quantity; 'remaining'/'left' means the earlier total minus everything consumed, sold, given away, or lost; 'total'/'altogether' means the sum over every group mentioned. Counts of indivisible things (people, animals, whole items, complete trips, full boxes) are whole numbers, so a division producing such a count must be floored with // or wrapped in int(); money and continuous measures may stay exact with /. Chain the intermediate quantities in order so each step uses the result of the previous one, and let the final expression evaluate to exactly the single quantity the question asks about, in the same unit the question asks for.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var spanCount: nat := 0;

// Tokens that should be discouraged once a symbolic expression is under way:
// nested span openers, prose separators, and disallowed operator surfaces.
var penaltyTokens: seq<Token> := ["<<", ">>", "*", "^", "=", "$", "\n", " step", "answer"];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Free reasoning prose; watch for the model's own "<<" opener.
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    // Inside a symbolic expression span: close as soon as it parses complete.
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      spanCount := spanCount + 1;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var spanLen := |currentConstrainedOut|;
      var next := eosToken;
      if spanLen <= 4 {
        // Early in the expression: prefer the caller-supplied symbol vocabulary
        // (variable names, digits, allowed operators) among parser-valid tokens.
        next := helpers.GroupBoostedConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 5.0, eosToken
        );
      } else if spanLen >= 24 {
        // Long span: discourage degenerate repetition so the expression can close.
        next := helpers.SafeRepetitionPenaltyStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
        );
      } else {
        // Mid-span: adaptive group preference plus penalties on nested openers
        // and disallowed operator surfaces.
        next := helpers.AdaptiveConstrainedStepWithPenalties(
          lm, parser, constrainedPrompt, currentConstrainedOut,
          validTokenGroups, 4.0, penaltyTokens, 4.0, 12, eosToken
        );
      }
      if next == eosToken {
        break;
      } else {
        var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
        if valid {
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        } else {
          // Parser rejected the sample (only possible on soft paths): repair by
          // shortening the constrained suffix back to a valid state.
          var rg, rc := helpers.RollbackConstrainedSuffix(parser, generated, currentConstrainedOut);
          generated := rg;
          currentConstrainedOut := rc;
        }
      }
    }
  }
}

