// CSD_RATIONALE_BEGIN
// Diagnosis of the previous attempt: the constrained machinery essentially never
// engaged (UnconstrainedStep dominated; constrained helper call fraction ~0.00).
// The reason is span-entry detection: the strategy only entered a span on exact
// token equality `next == "<<"`, but this tokenizer emits the opener fused with
// neighbouring text (" <<", "<<{") or split as "<" + "<". So most examples had a
// *visible* span with no parser control at all, which is why spans contained `{`,
// `}` and other unparseable surface, and why several examples rambled for the
// whole 900-step budget without ever producing a span.
//
// Three mechanism changes:
//  1. Robust span entry. After each free token I look at the concatenation of the
//     last two visible tokens and test it for the substring "<<" (CountSubstring).
//     That catches "<<", " <<", "<<{" and the split "<" + "<" case. On a hit I
//     call EnterObservedConstrainedSpan (cost 0, no duplicate delimiter) so every
//     byte after the opener is emitted under a hard parser mask - which is what
//     removes `{name}`-style braces and `**` from span content.
//  2. Guaranteed span existence. The free preamble is hard-capped at
//     workBudget - 70. If the model reaches that cap, or emits EOS before it has
//     ever produced a closed span, the strategy forces OpenConstrainedSpan and
//     spends the reserve on a parser-controlled final expression. That removes the
//     "no `<<` anywhere / hit max steps" mode entirely.
//  3. Sane closure policy, in both directions. Closing at the *first* complete
//     parse produced tiny junk spans (`<<initial_amount>>`). Here a span is closed
//     only when (a) the hard-masked step returns EOS, i.e. the model itself is done
//     with the expression, (b) the span reaches a length cap, or (c) the global
//     deadline is near; in cases (b)/(c) I first RollbackConstrainedToComplete so
//     the span is closed at a point the parser actually accepts, then
//     CloseSpanIfComplete emits ">>". Once the forced final span closes we stop, so
//     no junk span can overwrite the answer.
//  Total work is also capped at 800 steps to keep wall-clock margin, since masked
//  steps are more expensive than free ones.
//  Guidance carries only meaning the grammar cannot: braced placeholders name bare
//  variables, factor phrases multiply rather than replace, percent/"bigger than"
//  conventions, "first k of n" leaves n-k, solving for an unknown start amount, and
//  which quantities are whole counts.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   * Free-step branch, token is not an opener: insideConstrainedOut stays false and
//     currentConstrainedOut stays [], so the implication is vacuous.
//   * Free-step branch, opener observed: EnterObservedConstrainedSpan sets
//     insideOut := true and currentOut := [], and parser.IsValidPrefix([]) holds by
//     the method precondition.
//   * Forced-open branch: OpenConstrainedSpan sets insideOut := true and
//     currentOut := [], again valid by the precondition.
//   * Cap/deadline branch: RollbackConstrainedToComplete returns a parser-valid
//     (shorter) currentOut with |currentOut| <= |generatedOut|; CloseSpanIfComplete
//     either closes (insideOut := false, currentOut := [], implication vacuous) or
//     leaves the state untouched, so validity is preserved either way.
//   * Constrained-step branch: AdaptiveConstrainedStep returns EOS or a parser-valid
//     next token; on EOS we only attempt CloseSpanIfComplete (vacuous-or-unchanged);
//     otherwise IsTokenValidNext gates AppendConstrainedToken, whose postcondition
//     gives parser.IsValidPrefix(currentConstrained + [next]); the rollback fallback
//     returns a parser-valid shortened suffix.
// progress (|generated| <= |generatedPrefix| + steps):
//   * Free-step branch consumes exactly 1 token-step (steps + 1) and appends at most
//     one visible token; on EOS it appends nothing, so growth <= budget consumed.
//     EnterObservedConstrainedSpan appends nothing and consumes nothing.
//   * Forced-open branch consumes 1 token-step and appends exactly one "<<" token.
//   * Constrained-step branch consumes 1 token-step; either the token is appended
//     (growth 1) or it is EOS, which is consumed but not appended and the following
//     CloseSpanIfComplete appends at most one ">>" - visible growth is still at most
//     the 1 token-step charged for that iteration.
//   * Cap/deadline branch charges 1 token-step; the rollback only shrinks generated
//     and CloseSpanIfComplete appends at most one ">>", so growth <= 1.
//   Every iteration therefore keeps |generated| - |generatedPrefix| <= steps, and
//   steps <= workBudget <= maxSteps gives both |generated| <= |generatedPrefix| +
//   maxSteps and cost <= maxSteps. When maxSteps > 0 we have workBudget > 0, the body
//   runs, and every path (including every break, which follows its increment)
//   increases steps, so cost > 0.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string :=
  "In this problem family a name shown in braces, like {mult} or {n1}, is simply the variable named mult or n1; write the bare name in the arithmetic and never invent a numeric value for it. A factor phrase - 'X times that number', 'multiple the age', 'twice as many', 'mult as much' - multiplies the quantity it refers to, so that group equals the factor times the referenced quantity, and the bare referenced quantity is not the answer when the question asks for the scaled or derived value. 'each' and 'per' multiply the stated rate by the number of units it distributes over; 'p percent of q' is q*p/100; 'p% bigger than q' is q + q*p/100; 'half' and 'a quarter of' scale by /2 and /4. 'The first k of n groups' leaves n-k groups for any later clause about 'the last one' or 'the others combined'. 'Left' or 'remaining' subtracts everything spent, eaten, sold or given away from the earlier total; 'total' or 'altogether' adds every group mentioned; when the question asks for an unknown starting amount, solve the stated relation for it, for example start = total + used - added. Counts of indivisible things - people, whole items, complete trips, whole days a supply lasts - are whole numbers, so use // for that division or wrap the result in int(), while money and continuous measures may stay exact. Reason briefly, naming each quantity once, then state the single quantity the question asks about, built only from variables named in the question.";
helpers.AppendTaskGuidance(lm, guidance);

var workBudget: nat := maxSteps;
if workBudget > 800 {
  workBudget := 800;
}
var reserve: nat := 70;
var preambleCap: nat := 0;
if workBudget > reserve {
  preambleCap := workBudget - reserve;
}
var spanCap: nat := 44;

var steps: nat := 0;
var closedSpans: nat := 0;
var forceOpen: bool := false;
var forcedFinal: bool := false;

while steps < workBudget
  invariant 0 <= steps <= workBudget
  invariant workBudget <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases workBudget - steps
{
  if !insideConstrainedOut {
    if forceOpen || steps >= preambleCap {
      // Reserve budget is reached (or the model stopped without an answer span):
      // force a visible span so the answer is always emitted under parser control.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
      forceOpen := false;
      forcedFinal := true;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        if closedSpans > 0 {
          break;
        }
        forceOpen := true;
      } else {
        generated := generated + [next];
        // Robust opener detection: the delimiter may be fused into a token
        // (" <<", "<<{") or split across two tokens ("<" + "<").
        var tail: string := next;
        if |generated| >= 2 {
          tail := generated[|generated| - 2] + next;
        }
        var opens := CSDHelpers.CountSubstring(tail, "<<");
        if opens > 0 {
          var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := eg;
          insideConstrainedOut := ei;
          currentConstrainedOut := ec;
        }
      }
    }
  } else {
    if |currentConstrainedOut| >= spanCap || steps + 6 >= workBudget {
      // Span is too long, or the budget deadline is near: retreat to the last
      // point the parser accepts as complete and emit the closing delimiter.
      var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
      generated := rg;
      currentConstrainedOut := rc;
      var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      steps := steps + 1;
      if closed {
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        closedSpans := closedSpans + 1;
        if forcedFinal {
          break;
        }
      }
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // The model itself is finished with this expression: close it now.
        var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
        if closed {
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          closedSpans := closedSpans + 1;
          if forcedFinal {
            break;
          }
        }
      } else {
        var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
        if valid {
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        } else {
          var rg2, rc2 := helpers.RollbackConstrainedSuffix(parser, generated, currentConstrainedOut);
          generated := rg2;
          currentConstrainedOut := rc2;
        }
      }
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Diagnosis. Two distinct span-lifecycle bugs, both visible in the metrics.
//   (1) Tiny spans. "Visible span token length: avg 1.00" with 28 syntax-valid
//       wrong answers. Every inside-span token came from a *hard-masked* step
//       whose unmasked set is {parser-valid} ∪ {EOS}. When the model's true
//       preference is ">>" / whitespace / LaTeX (all masked out), EOS wins the
//       argmax, so the span stops after one token — or, in the 21
//       `final_span_unclosed` cases, before *any* token, leaving "<<" dangling.
//       Forcing a span open right after a natural EOS made this worse: the model
//       is finished, so it answers EOS forever and the span never fills or closes.
//   (2) Premature closure. Closing at the first complete parse turns
//       "(w1 + w2 + w3) * price" into "<<(w1)>>".
// Fixes, all inside the span:
//   * Content is now produced by SoftConstrainedStep (boost valid+EOS, sample
//     without a hard mask). If the sampled token is parser-valid we commit it, so
//     the expression follows the model's own continuation instead of a masked
//     surrogate — this is what stops the "total-1111111..." degeneracies and the
//     EOS collapse, because EOS is only returned when the model genuinely wants
//     to stop.
//   * `!softOk` (the model wanted ">>"/prose) or EOS is the *end signal*. It is
//     honoured only once the span holds >= minSpanLen tokens; below that the
//     strategy takes one hard AdaptiveConstrainedStepWithPenalties whose penalty
//     list contains eosToken, "<<", ">>", so the span is guaranteed to acquire
//     real content rather than closing empty or one token long.
//   * Closure is completeness-gated (CloseSpanIfComplete). If the end signal
//     arrives on an incomplete prefix ("total -"), one forced content token is
//     added and the next end signal closes it.
//   * Guaranteed termination of the span: a length cap, a stall counter, and a
//     deadline (steps + 10 >= workBudget) all route to
//     RollbackConstrainedToComplete + CloseSpanIfComplete, i.e. retreat to the
//     longest point the parser accepts and emit ">>". In the last 4 steps no
//     further content is generated, so the final action on a span is always a
//     close attempt and no incomplete tail survives the budget.
//   * The answer span is identified by scanning only the last 10 visible tokens
//     for "final answer"; once that span closes we stop, so no trailing "<<n>><<"
//     can overwrite the answer.
//   * workBudget capped at 640 steps keeps wall-clock well inside 90s even though
//     inside-span iterations may take two LM calls.
// Guidance carries only meaning the grammar cannot express: braces name bare
// variables, how per/percent/factor phrases distribute, and which quantities are
// whole counts.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   * Free-step branch, token has no "<<": insideConstrainedOut stays false and
//     currentConstrainedOut stays [], so the implication is vacuous.
//   * Free-step branch, opener observed: EnterObservedConstrainedSpan sets
//     insideOut := true, currentOut := [], and parser.IsValidPrefix([]) holds by
//     the method precondition.
//   * Forced-open branch: OpenConstrainedSpan sets insideOut := true and
//     currentOut := [], valid by the same precondition.
//   * Rollback branch: RollbackConstrainedToComplete returns a shortened
//     currentOut that is parser-valid (complete or empty) with
//     |currentOut| <= |generatedOut|, so the implication is preserved.
//   * Close branch: when CloseSpanIfComplete closes, insideOut := false and
//     currentOut := [], making the implication vacuous; when it does not close it
//     leaves state untouched, so the incoming validity still holds.
//   * Soft branch: SoftConstrainedStep's token is committed only after
//     IsTokenValidNext, and AppendConstrainedToken's postcondition then gives
//     parser.IsValidPrefix(currentConstrained + [next]); otherwise nothing is
//     appended.
//   * Forced-content branch: AdaptiveConstrainedStepWithPenalties returns EOS
//     (nothing appended, state unchanged and still valid) or a token gated again
//     by IsTokenValidNext before AppendConstrainedToken.
// progress (|generated| <= |generatedPrefix| + steps):
//   * Free step consumes exactly 1 token-step and appends at most one visible
//     token (zero on EOS); EnterObservedConstrainedSpan consumes and appends
//     nothing, so growth <= budget consumed.
//   * Forced open consumes 1 token-step and appends exactly one "<<".
//   * Rollback consumes 0 steps and only shrinks generated; the following
//     CloseSpanIfComplete consumes 1 token-step and appends at most one ">>".
//   * Soft step consumes 1 token-step and appends at most one token; a following
//     close attempt consumes another token-step and appends at most one ">>";
//     a following forced-content step consumes one more token-step and appends at
//     most one token. In every case visible growth in the iteration is at most the
//     number of token-steps charged for it, including EOS steps that consume
//     budget without appending anything.
//   Hence |generated| - |generatedPrefix| <= steps <= workBudget <= maxSteps gives
//   both the length bound and cost <= maxSteps. When maxSteps > 0 we get
//   workBudget > 0, the body runs, and every path (each break follows its own
//   increment) raises steps, so cost > 0.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string :=
  "A name shown in braces, like {mult} or {n1}, is simply the variable named mult or n1: write the bare name in the arithmetic and never substitute an invented number. Every quantity the question names keeps its variable name, and only quantities stated in the question or derived from them may appear. 'each' and 'per' multiply the stated rate by the number of units it distributes over; 'p percent of q' is q*p/100; 'p% more than q' is q + q*p/100; 'twice', 'half' and 'a quarter of' scale the referenced quantity by 2, /2 and /4; a factor phrase such as 'X times that number', 'multiple the age' or 'mult as much' multiplies the quantity it refers to, so the scaled value - not the bare referenced quantity - is what the question about it asks for. 'The first k of n groups' leaves n-k groups for any later clause about the last one or the others combined. 'Left' or 'remaining' is the earlier total minus everything spent, eaten, sold or given away; 'total' and 'altogether' sum every group mentioned; when the question asks for an unknown starting amount, solve the stated relation for it, for example start = total + used - added. Counts of indivisible things - people, whole items, complete trips, whole days a supply lasts - are whole numbers, so floor such a division with // or wrap the result in int(), while money and continuous measures may stay exact. Name each intermediate quantity once, chaining them in order, and let the final expression evaluate to exactly the single quantity the question asks about.";
helpers.AppendTaskGuidance(lm, guidance);

var workBudget: nat := maxSteps;
if workBudget > 640 {
  workBudget := 640;
}
var closeReserve: nat := 10;
var preambleCap: nat := workBudget;
if workBudget > 90 {
  preambleCap := workBudget - 90;
}
var minSpanLen: nat := 3;
var spanCap: nat := 40;
var penaltyTokens: seq<Token> := [eosToken, "<<", ">>", "$", "\n"];

var steps: nat := 0;
var spansClosed: nat := 0;
var finalSpan: bool := false;
var stalls: nat := 0;
var forcedOpenUsed: bool := false;
var forceOpenNow: bool := false;

while steps < workBudget
  invariant 0 <= steps <= workBudget
  invariant workBudget <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases workBudget - steps
{
  if !insideConstrainedOut {
    if (forceOpenNow || steps >= preambleCap) && !forcedOpenUsed {
      // Either the model stopped without ever producing an answer span, or the
      // free preamble reached its cap: open the answer span explicitly.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
      forcedOpenUsed := true;
      forceOpenNow := false;
      finalSpan := true;
      stalls := 0;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        if spansClosed > 0 || forcedOpenUsed {
          break;
        }
        forceOpenNow := true;
      } else {
        generated := generated + [next];
        // Opener detection: the delimiter may be fused into one token (" <<",
        // "<<{") or split across two adjacent tokens ("<" + "<").
        var tail: string := next;
        if |generated| >= 2 {
          tail := generated[|generated| - 2] + next;
        }
        var opens := CSDHelpers.CountSubstring(tail, "<<");
        if opens > 0 {
          var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := eg;
          insideConstrainedOut := ei;
          currentConstrainedOut := ec;
          // Only the immediate lead-in decides whether this is the answer span.
          var lo := 0;
          if |generated| > 10 {
            lo := |generated| - 10;
          }
          var tailText := CSDHelpers.PrefixToString(generated[lo..]);
          var f1 := CSDHelpers.CountSubstring(tailText, "final answer");
          var f2 := CSDHelpers.CountSubstring(tailText, "Final Answer");
          finalSpan := f1 + f2 > 0;
          stalls := 0;
        }
      }
    }
  } else {
    var tryClose := false;
    var forceContent := false;
    var nearEnd := steps + 4 >= workBudget;
    if |currentConstrainedOut| >= spanCap || steps + closeReserve >= workBudget || stalls >= 8 {
      // Cap, deadline or stall: retreat to the longest parser-complete point so
      // the closing delimiter can be emitted.
      var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
      generated := rg;
      currentConstrainedOut := rc;
      tryClose := true;
    } else {
      var cutLen := |generated| - |currentConstrainedOut|;
      var cprompt := prompt + generated[..cutLen];
      // Model-preferred continuation; an invalid or EOS choice is the model's
      // own signal that the expression is finished.
      var nextSoft, softOk := helpers.SoftConstrainedStep(
        lm, parser, cprompt, currentConstrainedOut, 3.0, eosToken
      );
      steps := steps + 1;
      var accepted := false;
      if softOk && nextSoft != eosToken {
        var okv := helpers.IsTokenValidNext(parser, currentConstrainedOut, nextSoft);
        if okv {
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, nextSoft
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
          accepted := true;
          stalls := 0;
        }
      }
      if !accepted {
        if |currentConstrainedOut| >= minSpanLen {
          tryClose := true;
        } else {
          // Too short to be a real expression: force content instead of closing.
          forceContent := true;
        }
      }
    }
    if tryClose && insideConstrainedOut {
      var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      steps := steps + 1;
      if closed {
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        spansClosed := spansClosed + 1;
        stalls := 0;
        if finalSpan {
          break;
        }
      } else {
        forceContent := true;
      }
    }
    if forceContent && !nearEnd && insideConstrainedOut && |currentConstrainedOut| <= |generated| {
      var cut2 := |generated| - |currentConstrainedOut|;
      var cprompt2 := prompt + generated[..cut2];
      var nx := helpers.AdaptiveConstrainedStepWithPenalties(
        lm, parser, cprompt2, currentConstrainedOut,
        validTokenGroups, 4.0, penaltyTokens, 6.0, 12, eosToken
      );
      steps := steps + 1;
      if nx != eosToken {
        var okv2 := helpers.IsTokenValidNext(parser, currentConstrainedOut, nx);
        if okv2 {
          var ag2, ai2, ac2 := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, nx
          );
          generated := ag2;
          insideConstrainedOut := ai2;
          currentConstrainedOut := ac2;
          stalls := 0;
        } else {
          stalls := stalls + 1;
        }
      } else {
        stalls := stalls + 1;
      }
    }
    if stalls >= 16 {
      break;
    }
  }
}

cost := steps;
